// Checks the inline crypto bundle of src/manager/manager.html against the shared proto-2
// test vectors (test/fixtures/proto2/vectors.json, generated by scripts/gen_vectors.mjs).
// The bundle is extracted from manager.html (between the EM-CRYPTO markers) and evaluated in a
// plain vm context that only provides crypto.getRandomValues, like a browser on a plain-HTTP origin.
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import vm from "node:vm";
import nodeCrypto from "node:crypto";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const html = fs.readFileSync(path.join(root, "src/manager/manager.html"), "utf8");
const vectors = JSON.parse(fs.readFileSync(path.join(root, "test/fixtures/proto2/vectors.json"), "utf8"));

const BEGIN = "/*EM-CRYPTO-BEGIN*/";
const END = "/*EM-CRYPTO-END*/";
const start = html.indexOf(BEGIN);
const end = html.indexOf(END);
assert.ok(start >= 0 && end > start, "manager.html must contain the EM-CRYPTO markers");
assert.equal(html.indexOf(BEGIN, start + 1), -1, "exactly one crypto block");
const code = html.slice(start + BEGIN.length, end);

const context = vm.createContext({
  crypto: { getRandomValues: (array) => nodeCrypto.getRandomValues(array) }, // the only platform primitive
});
vm.runInContext(code, context);
const C = context.EscapeCrypto;

const hex = (bytes) => Buffer.from(bytes).toString("hex");
const fromHex = (text) => new Uint8Array(Buffer.from(text, "hex"));

test("bundle exposes the documented API and nothing needs WebCrypto", () => {
  for (const name of ["deriveKeys", "deriveEditKeys", "hmacSha256", "sha256", "gcmSeal", "gcmOpen", "b64uEncode", "b64uDecode",
    "utf8Encode", "utf8Decode", "constantTimeEqual"]) {
    assert.equal(typeof C[name], "function", name);
  }
  assert.equal(context.crypto.subtle, undefined);
  assert.equal(Object.keys(context).includes("TextEncoder"), false, "bundle must not need TextEncoder");
});

for (const [index, v] of vectors.tokens.entries()) {
  const keys = () => C.deriveKeys(v.token, vectors.kdf.iter);

  test(`vector ${index}: key schedule (PBKDF2 + HKDF)`, () => {
    const k = keys();
    assert.equal(hex(k.req), v.kReq);
    assert.equal(hex(k.resp), v.kResp);
    assert.equal(hex(k.mac), v.kMac);
  });

  test(`vector ${index}: derived keys are cached per (token, iterations)`, () => {
    assert.strictEqual(C.deriveKeys(v.token, vectors.kdf.iter), keys());
    assert.notStrictEqual(C.deriveKeys(v.token, vectors.kdf.iter + 1), keys());
    assert.notStrictEqual(C.deriveKeys(v.token + "x", vectors.kdf.iter), keys());
  });

  test(`vector ${index}: POST envelope bytes (vector IV and t)`, () => {
    const k = keys();
    const iv = C.b64uDecode(v.post.iv);
    assert.equal(iv.length, 12);
    const aad = `EM2|req|${vectors.did}|${v.post.path}|${v.post.t}`;
    assert.equal(aad, v.post.aad);
    const ct = C.gcmSeal(k.req, iv, aad, v.post.plaintext);
    const envelope = JSON.stringify({ v: 2, t: v.post.t, iv: C.b64uEncode(iv), ct: C.b64uEncode(ct) });
    assert.equal(envelope, v.post.envelope);
    // and the device side can open what we sealed
    assert.equal(C.utf8Decode(C.gcmOpen(k.req, iv, aad, ct)), v.post.plaintext);
  });

  test(`vector ${index}: response envelope opens, tampering does not`, () => {
    const k = keys();
    const envelope = JSON.parse(v.postResponse.envelope);
    const iv = C.b64uDecode(envelope.iv);
    const sealed = C.b64uDecode(envelope.ct);
    const aad = `EM2|resp|${vectors.did}|${v.post.path}|${v.post.iv}|${v.postResponse.status}`;
    assert.equal(aad, v.postResponse.aad);
    assert.equal(C.utf8Decode(C.gcmOpen(k.resp, iv, aad, sealed)), v.postResponse.plaintext);

    const flipped = Uint8Array.from(sealed);
    flipped[0] ^= 1;
    assert.equal(C.gcmOpen(k.resp, iv, aad, flipped), null, "flipped ciphertext bit");
    const tagFlipped = Uint8Array.from(sealed);
    tagFlipped[tagFlipped.length - 1] ^= 0x80;
    assert.equal(C.gcmOpen(k.resp, iv, aad, tagFlipped), null, "flipped tag bit");
    assert.equal(C.gcmOpen(k.resp, iv, aad + "x", sealed), null, "wrong AAD");
    assert.equal(C.gcmOpen(k.resp, iv, aad.replace("|200", "|401"), sealed), null, "wrong status in AAD");
    assert.equal(C.gcmOpen(k.req, iv, aad, sealed), null, "wrong key");
    assert.equal(C.gcmOpen(k.resp, iv, aad, sealed.subarray(0, 8)), null, "shorter than the tag");
    assert.equal(C.gcmOpen(k.resp, iv, aad, new Uint8Array(0)), null, "empty");
    assert.equal(C.gcmOpen(k.resp, iv.subarray(0, 8), aad, sealed), null, "malformed IV");
  });

  test(`vector ${index}: GET frame MAC and slicing`, () => {
    const k = keys();
    const g = v.get;
    const message = `EM2|get|${vectors.did}|${g.path}|${g.nonce}|${g.status}|${g.doc}`;
    const mac = C.b64uEncode(C.hmacSha256(k.mac, message));
    assert.equal(g.frame, `{"doc":${g.doc},"mac":"${mac}"}`);

    // the manager's own slicing rules (PROTOCOL.md 4.1)
    const text = g.frame;
    const tail = text.lastIndexOf(',"mac":"');
    assert.ok(text.startsWith('{"doc":') && tail > 0 && text.endsWith('"}'));
    assert.equal(text.slice(7, tail), g.doc);
    const supplied = C.b64uDecode(text.slice(tail + 8, -2));
    assert.equal(supplied.length, 32);
    assert.equal(C.constantTimeEqual(supplied, C.hmacSha256(k.mac, message)), true);
    // another device id / path / nonce / status never verifies
    for (const wrong of [
      `EM2|get|aabbccddee00|${g.path}|${g.nonce}|${g.status}|${g.doc}`,
      `EM2|get|${vectors.did}|/peers.json|${g.nonce}|${g.status}|${g.doc}`,
      `EM2|get|${vectors.did}|${g.path}|${g.nonce}x|${g.status}|${g.doc}`,
      `EM2|get|${vectors.did}|${g.path}|${g.nonce}|404|${g.doc}`,
    ]) {
      assert.equal(C.constantTimeEqual(supplied, C.hmacSha256(k.mac, wrong)), false, wrong);
    }
  });

  test(`vector ${index}: UDP frame MAC`, () => {
    const k = keys();
    const mac = C.b64uEncode(C.hmacSha256(k.mac, "EM2|udp|" + v.udp.doc));
    assert.equal(v.udp.frame, `{"doc":${v.udp.doc},"mac":"${mac}"}`);
  });
}

test("b64u: valid vectors encode and decode", () => {
  for (const item of vectors.b64u) {
    assert.equal(C.b64uEncode(fromHex(item.hex)), item.text, item.hex);
    assert.equal(hex(C.b64uDecode(item.text)), item.hex, item.text);
  }
});

test("b64u: every invalid vector is rejected with null", () => {
  for (const text of vectors.b64uInvalid) assert.equal(C.b64uDecode(text), null, JSON.stringify(text));
  for (const text of ["", "AA==", "AAA=", "ab+/", "ab_/", "A\u00e4AA", "AA\n", " AAAA", "AAAAA", 7, null, undefined, {}]) {
    if (text === "") continue; // the empty string is a valid empty value
    assert.equal(C.b64uDecode(text), null, JSON.stringify(text));
  }
  assert.equal(C.b64uDecode("").length, 0);
});

test("b64u: round trip equals Node's base64url for all small lengths", () => {
  for (let length = 0; length < 70; length++) {
    const bytes = nodeCrypto.randomBytes(length);
    const text = bytes.toString("base64url");
    assert.equal(C.b64uEncode(bytes), text);
    assert.equal(hex(C.b64uDecode(text)), bytes.toString("hex"));
  }
});

test("HKDF-SHA256 matches RFC 5869 test case 1", () => {
  const h = vectors.hkdfRfc5869;
  assert.equal(hex(C.hkdfSha256(fromHex(h.ikm), fromHex(h.salt), fromHex(h.info), h.length)), h.okm);
});

test("sha256 / hmac / gcm basics against Node", () => {
  assert.equal(hex(C.sha256("abc")), nodeCrypto.createHash("sha256").update("abc").digest("hex"));
  assert.equal(hex(C.sha256(new Uint8Array(0))), nodeCrypto.createHash("sha256").update("").digest("hex"));
  // RFC 4231 test case 2
  assert.equal(hex(C.hmacSha256("Jefe", "what do ya want for nothing?")),
    "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843");
  for (const length of [0, 1, 15, 16, 17, 31, 32, 33, 100, 1000]) {
    const key = nodeCrypto.randomBytes(32), iv = nodeCrypto.randomBytes(12), plain = nodeCrypto.randomBytes(length);
    const cipher = nodeCrypto.createCipheriv("aes-256-gcm", key, iv);
    cipher.setAAD(Buffer.from("aad"));
    const expected = Buffer.concat([cipher.update(plain), cipher.final(), cipher.getAuthTag()]);
    assert.equal(hex(C.gcmSeal(key, iv, "aad", plain)), expected.toString("hex"), "length " + length);
    assert.equal(hex(C.gcmOpen(key, iv, "aad", expected)), plain.toString("hex"));
  }
});

test("constantTimeEqual", () => {
  assert.equal(C.constantTimeEqual(fromHex("0102"), fromHex("0102")), true);
  assert.equal(C.constantTimeEqual(fromHex("0102"), fromHex("0103")), false);
  assert.equal(C.constantTimeEqual(fromHex("0102"), fromHex("010203")), false);
  assert.equal(C.constantTimeEqual(new Uint8Array(0), new Uint8Array(0)), true);
});

test("utf8 encode/decode agree with the platform, invalid input becomes U+FFFD", () => {
  for (const text of ["", "abc", "Käfig/Ü", "日本語", "😀 emoji", "\u0000\u007f\u0080\u07ff\u0800\uffff"]) {
    assert.equal(hex(C.utf8Encode(text)), Buffer.from(text).toString("hex"), text);
    assert.equal(C.utf8Decode(C.utf8Encode(text)), text);
  }
  assert.equal(hex(C.utf8Encode("\ud800")), Buffer.from("\ufffd").toString("hex"), "lone surrogate");
  const decoder = new TextDecoder();
  for (const bad of ["ff", "c0af", "e080af", "eda080", "f4908080", "e282", "41c3", "f0908d", "80", "c328"]) {
    assert.equal(C.utf8Decode(fromHex(bad)), decoder.decode(fromHex(bad)), bad);
  }
  assert.equal(C.utf8Decode(new Uint8Array(20000).fill(0x61)).length, 20000, "long input");
});

test("deriveKeys refuses iteration counts outside 1..100000", () => {
  assert.throws(() => C.deriveKeys("a-token", 100001), { name: "RangeError" });
  assert.throws(() => C.deriveKeys("a-token", 0), { name: "RangeError" });
  assert.throws(() => C.deriveKeys("a-token", 1.5), { name: "RangeError" });
});

test("randomBytes uses crypto.getRandomValues only", () => {
  const a = C.randomBytes(16), b = C.randomBytes(16);
  assert.equal(a.length, 16);
  assert.notEqual(hex(a), hex(b));
});

// ---- plan-edit token (PROTOCOL.md 3.1), vectors key "edit" ----

const E = vectors.edit;
const editKeys = () => C.deriveEditKeys(E.editToken, vectors.kdf.iter);

test("edit: key schedule (salt EscapeManager/2/edit-token, same iterations and HKDF infos)", () => {
  assert.equal(E.salt, "EscapeManager/2/edit-token");
  const k = editKeys();
  assert.equal(hex(k.req), E.kReq);
  assert.equal(hex(k.resp), E.kResp);
  assert.equal(hex(k.mac), E.kMac);
  // the master itself is PBKDF2 with the edit salt: check it against Node
  const master = nodeCrypto.pbkdf2Sync(Buffer.from(E.editToken), E.salt, vectors.kdf.iter, 32, "sha256");
  assert.equal(master.toString("hex"), E.master);
  // the same token under the NORMAL salt gives different keys (the two key sets are independent)
  assert.notEqual(hex(C.deriveKeys(E.editToken, vectors.kdf.iter).req), E.kReq);
  assert.notEqual(hex(C.deriveKeys(E.editToken, vectors.kdf.iter).mac), E.kMac);
});

test("edit: derived keys are cached per (token, iterations) and kept apart from the normal key cache", () => {
  assert.strictEqual(C.deriveEditKeys(E.editToken, vectors.kdf.iter), editKeys());
  assert.notStrictEqual(C.deriveEditKeys(E.editToken, vectors.kdf.iter + 1), editKeys());
  assert.notStrictEqual(C.deriveEditKeys(E.editToken + "x", vectors.kdf.iter), editKeys());
  // the same string as normal and as edit token must not share a cache slot
  assert.notStrictEqual(C.deriveKeys(E.editToken, vectors.kdf.iter), editKeys());
  assert.strictEqual(C.deriveKeys(E.editToken, vectors.kdf.iter), C.deriveKeys(E.editToken, vectors.kdf.iter));
});

test("edit: deriveEditKeys refuses iteration counts outside 1..100000", () => {
  assert.throws(() => C.deriveEditKeys("a-token-1234", 100001), { name: "RangeError" });
  assert.throws(() => C.deriveEditKeys("a-token-1234", 0), { name: "RangeError" });
});

test("edit: the edit-keyed POST envelope is byte-identical, \"k\":\"e\" is the LAST member", () => {
  const k = editKeys();
  const iv = C.b64uDecode(E.post.iv);
  const aad = `EM2|req|${vectors.did}|${E.post.path}|${E.post.t}`;
  assert.equal(aad, E.post.aad);
  const ct = C.gcmSeal(k.req, iv, aad, E.post.plaintext);
  const envelope = JSON.stringify({ v: 2, t: E.post.t, iv: C.b64uEncode(iv), ct: C.b64uEncode(ct), k: "e" });
  assert.equal(envelope, E.post.envelope);
  assert.ok(envelope.endsWith(',"k":"e"}'));
  assert.equal(C.utf8Decode(C.gcmOpen(k.req, iv, aad, ct)), E.post.plaintext);
});

test("edit: the same request sealed with the NORMAL keys (no k) matches, and the two ciphertexts differ", () => {
  const normal = C.deriveKeys(E.normalToken, vectors.kdf.iter);
  const iv = C.b64uDecode(E.post.iv);
  const aad = E.post.aad;
  const ct = C.gcmSeal(normal.req, iv, aad, E.post.plaintext);
  assert.equal(JSON.stringify({ v: 2, t: E.post.t, iv: C.b64uEncode(iv), ct: C.b64uEncode(ct) }), E.post.normalEnvelope);
  assert.notEqual(JSON.parse(E.post.envelope).ct, JSON.parse(E.post.normalEnvelope).ct);
  // neither key set opens the other one's ciphertext: a stripped or added "k" just fails authentication
  const editCt = C.b64uDecode(JSON.parse(E.post.envelope).ct);
  assert.equal(C.gcmOpen(normal.req, iv, aad, editCt), null);
  assert.equal(C.gcmOpen(editKeys().req, iv, aad, ct), null);
});

test("edit: the response envelope opens with the edit response key only", () => {
  const k = editKeys();
  const normal = C.deriveKeys(E.normalToken, vectors.kdf.iter);
  const envelope = JSON.parse(E.postResponse.envelope);
  const iv = C.b64uDecode(envelope.iv);
  const sealed = C.b64uDecode(envelope.ct);
  const aad = `EM2|resp|${vectors.did}|${E.post.path}|${E.post.iv}|${E.postResponse.status}`;
  assert.equal(aad, E.postResponse.aad);
  assert.equal(C.utf8Decode(C.gcmOpen(k.resp, iv, aad, sealed)), E.postResponse.plaintext);
  assert.equal(C.gcmOpen(normal.resp, iv, aad, sealed), null, "the normal response key does not open an edit-keyed answer");
  assert.equal(C.gcmOpen(k.resp, iv, aad.replace("|200", "|401"), sealed), null, "status is bound");
  // a client tries the edit key first and then the normal one: both orders find the right key
  const tryKeys = (keys) => keys.map((key) => C.gcmOpen(key, iv, aad, sealed)).find(Boolean);
  assert.equal(C.utf8Decode(tryKeys([k.resp, normal.resp])), E.postResponse.plaintext);
  assert.equal(C.utf8Decode(tryKeys([normal.resp, k.resp])), E.postResponse.plaintext);
});

test("edit: GET /edit.json proof frame (domain EM2|eget|, edit mac key)", () => {
  const k = editKeys();
  const normal = C.deriveKeys(E.normalToken, vectors.kdf.iter);
  const p = E.proof;
  const message = (domain, did = vectors.did, nonce = p.nonce, status = p.status) => `${domain}|${did}|${p.path}|${nonce}|${status}|${p.doc}`;
  const mac = C.b64uEncode(C.hmacSha256(k.mac, message("EM2|eget")));
  assert.equal(p.frame, `{"doc":${p.doc},"mac":"${mac}"}`);
  // verified the way the manager verifies it (slicing the exact bytes)
  const tail = p.frame.lastIndexOf(',"mac":"');
  assert.equal(p.frame.slice(7, tail), p.doc);
  const supplied = C.b64uDecode(p.frame.slice(tail + 8, -2));
  assert.equal(C.constantTimeEqual(supplied, C.hmacSha256(k.mac, message("EM2|eget"))), true);
  // nothing else verifies: normal mac key, the normal GET domain, another device, nonce or status
  for (const wrong of [
    C.hmacSha256(normal.mac, message("EM2|eget")),
    C.hmacSha256(k.mac, message("EM2|get")),
    C.hmacSha256(k.mac, message("EM2|eget", "aabbccddee00")),
    C.hmacSha256(k.mac, message("EM2|eget", vectors.did, p.nonce + "x")),
    C.hmacSha256(k.mac, message("EM2|eget", vectors.did, p.nonce, 404)),
  ]) assert.equal(C.constantTimeEqual(supplied, wrong), false);
  assert.equal(p.doc, '{"proto":2,"edit":"custom"}');
});

test("edit: skeleton MAC (EM2|skel|room|rev|hash8, edit mac key) - computed here only to check vectors, the manager never recomputes it", () => {
  const k = editKeys();
  const sk = E.skeleton;
  const emac = C.b64uEncode(C.hmacSha256(k.mac, `EM2|skel|${sk.room}|${sk.rev}|${sk.hash}`));
  assert.equal(emac, sk.emac);
  assert.equal(C.b64uDecode(sk.emac).length, 32);
  // bound to room, revision and hash
  for (const wrong of [`EM2|skel|${sk.room}x|${sk.rev}|${sk.hash}`, `EM2|skel|${sk.room}|${sk.rev + 1}|${sk.hash}`, `EM2|skel|${sk.room}|${sk.rev}|0${sk.hash.slice(1)}`]) {
    assert.notEqual(C.b64uEncode(C.hmacSha256(k.mac, wrong)), sk.emac);
  }
  assert.notEqual(C.b64uEncode(C.hmacSha256(C.deriveKeys(E.normalToken, vectors.kdf.iter).mac, `EM2|skel|${sk.room}|${sk.rev}|${sk.hash}`)), sk.emac);
});
